import multer from "multer";

const upload = multer({
  storage: multer.diskStorage({
    destination: "./public/uploads",
    filename: (req, file, cb) => cb(null, file.originalname),
  }),
});

console.log(upload);
export const config = {
  api: {
    bodyParser: false,
  },
};
